CREATE TABLE "authors" (
  "au_id" CHAR(11) NOT NULL,
  "au_lname" VARCHAR(40) NOT NULL,
  "au_fname" VARCHAR(20) NOT NULL,
  "phone" CHAR(12) NOT NULL DEFAULT 'UNKNOWN',
  "address" VARCHAR(40),
  "city" VARCHAR(20),
  "state" CHAR(2),
  "zip" CHAR(5),
  "contract" TINYINT NOT NULL,
  PRIMARY KEY ("au_id"),
  CONSTRAINT "authors_chk_1" CHECK ("au_id" GLOB '[0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9][0-9][0-9]'),
  CONSTRAINT "authors_chk_2" CHECK ("zip" GLOB '[0-9][0-9][0-9][0-9][0-9]')
);

CREATE TABLE "stores" (
  "stor_id" CHAR(4) NOT NULL,
  "stor_name" VARCHAR(40),
  "stor_address" VARCHAR(40),
  "city" VARCHAR(20),
  "state" CHAR(2),
  "zip" CHAR(5),
  PRIMARY KEY ("stor_id")
);

CREATE TABLE "discounts" (
  "discounttype" VARCHAR(40) NOT NULL,
  "stor_id" CHAR(4),
  "lowqty" SMALLINT,
  "highqty" SMALLINT,
  "discount" DECIMAL(4,2) NOT NULL,
  CONSTRAINT "discounts_ibfk_1" FOREIGN KEY ("stor_id") REFERENCES "stores" ("stor_id") ON UPDATE NO ACTION ON DELETE NO ACTION
);

CREATE TABLE "jobs" (
  "job_id" INTEGER PRIMARY KEY,
  "job_desc" VARCHAR(50) NOT NULL DEFAULT 'New Position - title not formalized yet',
  "min_lvl" TINYINT NOT NULL,
  "max_lvl" TINYINT NOT NULL,
  CONSTRAINT "jobs_chk_1" CHECK (("min_lvl" >= 10)),
  CONSTRAINT "jobs_chk_2" CHECK (("max_lvl" <= 250))
);

CREATE TABLE "publishers" (
  "pub_id" CHAR(4) NOT NULL,
  "pub_name" VARCHAR(40),
  "city" VARCHAR(20),
  "state" CHAR(2),
  "country" VARCHAR(30) DEFAULT 'USA',
  PRIMARY KEY ("pub_id"),
  CONSTRAINT "publishers_chk_1" CHECK ((("pub_id" in ('1389','0736','0877','1622','1756')) or "pub_id" GLOB '99[0-9][0-9]'))
);

CREATE TABLE "employee" (
  "emp_id" CHAR(10) NOT NULL,
  "fname" VARCHAR(20) NOT NULL,
  "minit" CHAR(1),
  "lname" VARCHAR(30) NOT NULL,
  "job_id" SMALLINT NOT NULL DEFAULT 1,
  "job_lvl" TINYINT DEFAULT 10,
  "pub_id" CHAR(4) NOT NULL DEFAULT '9952',
  "hire_date" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("emp_id"),
  CONSTRAINT "employee_ibfk_1" FOREIGN KEY ("job_id") REFERENCES "jobs" ("job_id") ON UPDATE NO ACTION ON DELETE NO ACTION,
  CONSTRAINT "employee_ibfk_2" FOREIGN KEY ("pub_id") REFERENCES "publishers" ("pub_id") ON UPDATE NO ACTION ON DELETE NO ACTION,
  CONSTRAINT "employee_chk_1" CHECK (("emp_id" GLOB '[A-Za-z][A-Za-z][A-Za-z][1-9][0-9][0-9][0-9][0-9][FfMm]' or "emp_id" GLOB '[A-Za-z]-[A-Za-z][1-9][0-9][0-9][0-9][0-9][FfMm]'))
);

CREATE TABLE "pub_info" (
  "pub_id" CHAR(4) NOT NULL,
  "logo" BLOB,
  "pr_info" TEXT,
  PRIMARY KEY ("pub_id"),
  CONSTRAINT "pub_info_ibfk_1" FOREIGN KEY ("pub_id") REFERENCES "publishers" ("pub_id") ON UPDATE NO ACTION ON DELETE NO ACTION
);

CREATE TABLE "titles" (
  "title_id" CHAR(6) NOT NULL,
  "title" VARCHAR(80) NOT NULL,
  "type" CHAR(12) NOT NULL DEFAULT 'UNDECIDED',
