  "price" DECIMAL(19,4),
  "advance" DECIMAL(19,4),
  "royalty" INTEGER,
  "ytd_sales" INTEGER,
  "notes" VARCHAR(200),
  "pubdate" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("title_id"),
  CONSTRAINT "titles_ibfk_1" FOREIGN KEY ("pub_id") REFERENCES "publishers" ("pub_id") ON UPDATE NO ACTION ON DELETE NO ACTION
);

CREATE TABLE "roysched" (
  "title_id" CHAR(6),
  "lorange" INTEGER,
  "hirange" INTEGER,
  "royalty" INTEGER,
  CONSTRAINT "roysched_ibfk_1" FOREIGN KEY ("title_id") REFERENCES "titles" ("title_id") ON UPDATE NO ACTION ON DELETE NO ACTION
);

CREATE TABLE "sales" (
  "stor_id" CHAR(4) NOT NULL,
  "ord_num" VARCHAR(20) NOT NULL,
  "ord_date" DATETIME NOT NULL,
