  PRIMARY KEY ("stor_id", "ord_num", "title_id"),
  CONSTRAINT "sales_ibfk_1" FOREIGN KEY ("stor_id") REFERENCES "stores" ("stor_id") ON UPDATE NO ACTION ON DELETE NO ACTION,
  CONSTRAINT "sales_ibfk_2" FOREIGN KEY ("title_id") REFERENCES "titles" ("title_id") ON UPDATE NO ACTION ON DELETE NO ACTION
);

CREATE TABLE "titleauthor" (
  "au_id" CHAR(11) NOT NULL,
  "title_id" CHAR(6) NOT NULL,
  "au_ord" TINYINT,
  "royaltyper" INTEGER,
  PRIMARY KEY ("au_id", "title_id"),
  CONSTRAINT "titleauthor_ibfk_1" FOREIGN KEY ("au_id") REFERENCES "authors" ("au_id") ON UPDATE NO ACTION ON DELETE NO ACTION,
  CONSTRAINT "titleauthor_ibfk_2" FOREIGN KEY ("title_id") REFERENCES "titles" ("title_id") ON UPDATE NO ACTION ON DELETE NO ACTION
);

